#!/usr/bin/env bash
# check-generated-test.sh tests hack/check-generated.sh in a repository of
# its own under the temporary directory: one file per version line the
# check knows and some it does not, committed, then changed one way per case. A case names what it
# changes and whether the check must pass; the lint job of ci.yml runs it.
set -euo pipefail

check=$(cd "$(dirname "$0")" && pwd)/check-generated.sh
repo=$(mktemp -d)
trap 'rm -rf "$repo"' EXIT
cd "$repo"

fixture() {
	mkdir -p gen
	cat >gen/function.c <<'EOF'
// Generated by `wit-bindgen` 0.62.0. DO NOT EDIT!
#include "function.h"
const char *generator = "// Generated by `wit-bindgen` 0.62.0. DO NOT EDIT!";
EOF
	cat >gen/bindings.go <<'EOF'
// Generated by `wit-bindgen` 0.62.0. DO NOT EDIT!
package bindings
EOF
	cat >gen/top.mbt <<'EOF'
// Generated by `wit-bindgen` 0.62.0. DO NOT EDIT!
pub fn run() -> Unit {}
EOF
	cat >gen/run_function.pb.h <<'EOF'
/* Automatically generated nanopb header */
/* Generated by nanopb-0.4.9.1 */

#include <pb.h>
EOF
	cat >gen/run_function_pb.js <<'EOF'
// A license.

// @generated by protoc-gen-es v2.14.0 with parameter "target=js+dts,import_extension=js"
// @generated from file run_function.proto (package apiextensions.fn.proto.v1, syntax proto3)
export const file_run_function = 1;
EOF
	cat >gen/run_function_pb2.py <<'EOF'
# Generated by the protocol buffer compiler.  DO NOT EDIT!
# Protobuf Python Version: 7.35.1
"""Generated protocol buffer code."""
_runtime_version.ValidateProtobufRuntimeVersion(
    _runtime_version.Domain.PUBLIC,
    7,
    35,
    1,
    '',
    'run_function.proto'
)
DESCRIPTOR = build(
    7,
    35,
    1,
)
EOF
	printf 'hand-written\n' >gen/run.go
}

git init -q .
git config user.name test
git config user.email test@example.org
git config commit.gpgsign false
fixture
git add -A
git commit -q -m fixture

failed=0
# expect <pass|fail> <name>: runs the check over the tree the case left and
# puts the fixture back.
expect() {
	local want=$1 name=$2 got=pass
	# A case that changed nothing would pass for no reason.
	if [ "$name" != "a clean tree" ] && [ -z "$(git status --porcelain)" ]; then
		echo "FAIL $name: the case changed nothing"
		failed=1
		return
	fi
	if ! out=$("$check" -m "the hint" 2>&1); then
		got=fail
	fi
	if [ "$got" = "$want" ]; then
		echo "ok   $name"
	else
		echo "FAIL $name: the check must $want, and it did not:"
		printf '%s\n' "$out" | sed 's/^/     /'
		failed=1
	fi
	git reset -q --hard
	git clean -q -fdx
}

replace() {
	perl -0pi -e "$1" "$2"
}

expect pass "a clean tree"

replace 's/0\.62\.0/0.63.0/' gen/function.c
expect fail "the wit-bindgen version, which is compared like any line"

replace 's/nanopb-0\.4\.9\.1/nanopb-0.4.9.3/' gen/run_function.pb.h
expect pass "the nanopb version alone"

replace 's/v2\.14\.0/v2.17.0/' gen/run_function_pb.js
expect pass "the protoc-gen-es version alone"

replace 's/Version: 7\.35\.1/Version: 7.36.2/; s/    35,\n    1,\n    \x27\x27/    36,\n    2,\n    \x27\x27/' gen/run_function_pb2.py
expect pass "the protoc version of the python codec alone"

replace 's/nanopb-0\.4\.9\.1/nanopb-0.4.9.3/' gen/run_function.pb.h
replace 's/v2\.14\.0/v2.17.0/' gen/run_function_pb.js
expect pass "several versions at once"

replace 's/nanopb-0\.4\.9\.1/nanopb-0.4.9.3/; s/#include <pb\.h>/#include <pb2.h>/' gen/run_function.pb.h
expect fail "a version and a line after it"

replace 's/#include <pb\.h>/#include <pb2.h>/' gen/run_function.pb.h
expect fail "a line that states no version"

replace 's/^\/\* Generated by nanopb.*\n//m' gen/run_function.pb.h
expect fail "a version line removed"

replace 's/Generated by nanopb-/Made by nanopb-/' gen/run_function.pb.h
expect fail "a version line reworded"

replace 's/target=js\+dts/target=ts/' gen/run_function_pb.js
expect fail "the protoc-gen-es parameters"

replace 's/DESCRIPTOR = build\(\n    7,/DESCRIPTOR = build(\n    8,/' gen/run_function_pb2.py
expect fail "a number outside the python runtime check"

replace 's/Domain\.PUBLIC/Domain.INTERNAL/' gen/run_function_pb2.py
expect fail "the domain of the python runtime check"

replace 's/hand-written/0.63.0/' gen/run.go
expect fail "a file that states no version"

# shellcheck disable=SC2016
printf '// Generated by `wit-bindgen` 0.63.0. DO NOT EDIT!\n' >gen/new.go
expect fail "an untracked file"

mkdir -p gen/imports
printf 'package imports\n' >gen/imports/wit_bindings.go
expect fail "an untracked directory"

rm gen/top.mbt
expect fail "a deleted file"

chmod +x gen/function.c
expect fail "a file mode"

mkdir -p other
printf 'x\n' >other/new.txt
if (cd gen && "$check" . >/dev/null 2>&1); then
	echo "ok   a path limits the check"
else
	echo "FAIL a path limits the check: gen is clean"
	failed=1
fi
expect fail "an untracked file elsewhere, with no path given"

exit "$failed"
